WFJ.Data.add("book", {
  ["8c7b5832433c3203"] = { "Abyssal Duke\n\nSolo gli accoliti in possesso di un medaglione di rango possono stabilire un contatto con gli Abyssal Duke. I medaglioni di rango possono essere usati solo dalle persone a cui sono stati originariamente consegnati.\n\nI membri del ⟦Twilight's Hammer=Martello del Crepuscolo⟧ coinvolti in comunicazioni non approvate con gli Abyssal Duke o nell'uso non autorizzato dei medaglioni di rango saranno puniti da me personalmente.", "." },
  ["8c7fb6d0b54b1814"] = { "Al centro del continente, i Titani crearono un lago di energie scintillanti. Il lago, che chiamarono ⟦Well of Eternity=Pozzo dell'Eternità⟧, sarebbe stato la fonte della vita del mondo. Le sue potenti energie avrebbero nutrito le ossa del mondo e permesso alla vita di mettere radici nel suolo fertile. Col tempo, piante, alberi, mostri e creature di ogni genere iniziarono a prosperare sul continente primordiale.", "." },
  ["8ca3076632c5e85a"] = { "La parola TRADITORE è rozzamente graffiata sopra l'epitaffio finemente inciso, che recita:\n\nQui giace Yuriv.\nPadre, Marito, Paladino.\nChe i suoi figli testimonino che la sua devozione alla Luce era indiscutibile.\nNon avrebbe mai chiesto loro nulla che lui stesso non avrebbe fatto.", "." },
  ["8cb669ab3f520567"] = { "Il Pantheon, turbato dall'inclinazione al male degli Dei Antichi, mosse guerra agli elementali e ai loro oscuri padroni. Gli eserciti degli Dei Antichi erano guidati dai più potenti luogotenenti elementali: Ragnaros il Signore del Fuoco, Therazane la Madre di Pietra, Al'Akir il Signore del Vento e Neptulon the Tidehunter.", "." },
